style.css:
/* ================================
   Millennial Pink Theme for Stylish
   ================================ */

/* COLOR VARIABLES */
:root {
  --pink-main: #f4a6b8;        /* Millennial pink base */
  --pink-soft: #f8c6d1;        /* Lighter pink accents */
  --pink-dark: #e38aa0;        /* Hover / contrast pink */
  --white-main: #ffffff;       /* Primary text */
  --white-soft: #fff5f8;       /* Soft white backgrounds */
}

/* GLOBAL BACKGROUND */
html, body {
  background-color: var(--pink-main) !important;
  color: var(--white-main) !important;
}

/* TEXT */
p, span, li, label, div {
  color: var(--white-main) !important;
}

/* HEADERS */
h1, h2, h3, h4, h5, h6 {
  color: var(--white-main) !important;
  letter-spacing: 0.03em;
}

/* LINKS */
a {
  color: var(--white-soft) !important;
  text-decoration: none !important;
}

a:hover {
  color: var(--pink-soft) !important;
  text-decoration: underline !important;
}

/* BUTTONS */
button,
input[type="button"],
input[type="submit"] {
  background-color: var(--white-main) !important;
  color: var(--pink-main) !important;
  border: none !important;
  border-radius: 12px !important;
  padding: 8px 14px !important;
  font-weight: 600 !important;
}

button:hover,
input[type="button"]:hover,
input[type="submit"]:hover {
  background-color: var(--pink-soft) !important;
  color: var(--white-main) !important;
}

/* INPUT FIELDS */
input,
textarea,
select {
  background-color: var(--white-soft) !important;
  color: #333 !important;
  border: 2px solid var(--pink-dark) !important;
  border-radius: 10px !important;
  padding: 6px !important;
}

/* CARDS / CONTAINERS */
div,
section,
article,
main {
  background-color: transparent !important;
}

/* NAVBARS */
nav,
header {
  background-color: var(--pink-dark) !important;
  color: var(--white-main) !important;
}

/* FOOTERS */
footer {
  background-color: var(--pink-dark) !important;
  color: var(--white-soft) !important;
}

/* SCROLLBAR (Chrome) */
::-webkit-scrollbar {
  width: 10px;
}

::-webkit-scrollbar-track {
  background: var(--pink-soft);
}

::-webkit-scrollbar-thumb {
  background: var(--pink-dark);
  border-radius: 10px;
}

/* SELECTION */
::selection {
  background: var(--white-main);
  color: var(--pink-main);
}
